import numpy as np

def numerical_gradient(f, x: np.ndarray, eps: float = 1e-5) -> list:
    grad = np.zeros_like(x, dtype=float)
    for i in range(len(x)):
        x_plus = x.copy()
        x_minus = x.copy()
        x_plus[i] += eps
        x_minus[i] -= eps
        grad[i] = (f(x_plus) - f(x_minus)) / (2.0 * eps)
    return np.round(grad, 4).tolist()

A_demo = np.array([[2.0, 1.0], [1.0, 3.0]])
b_demo = np.array([-1.0, 2.0])
def test_func(x_vec):
    return float(x_vec.T @ A_demo @ x_vec + b_demo.T @ x_vec)

x_test = np.array([1.0, 2.0])
numerical_gradient(test_func, x_test)

exercises.tests:
def f2(x):
    return float(x[0]**2 + 3 * x[1]**2 - 4 * x[0])
g2 = numerical_gradient(f2, np.array([2.0, 1.0]))
assert g2 == [0.0, 6.0], f"数值梯度计算错误: {g2}"

