def bayes_disease_posterior(prior: float, sensitivity: float, specificity: float) -> tuple:
    p_pos = sensitivity * prior + (1.0 - specificity) * (1.0 - prior)
    posterior = (sensitivity * prior) / p_pos
    return (round(p_pos, 4), round(posterior, 4))

bayes_disease_posterior(0.01, 0.95, 0.90)

def gradient_descent_1d(f_grad, x0: float, lr: float, max_iters: int = 100, tol: float = 1e-6) -> tuple:
    x = float(x0)
    iters = 0
    for k in range(max_iters):
        g = f_grad(x)
        if abs(g) < tol:
            break
        x = x - lr * g
        iters += 1
    return (round(x, 4), iters)

def test_grad(x):
    return 2.0 * x - 4.0

gradient_descent_1d(test_grad, x0=10.0, lr=0.1, max_iters=100)

