def grad_test2(x):
    return 4.0 * (x - 3.0)
res2 = gradient_descent_1d(grad_test2, x0=5.0, lr=0.1, max_iters=50)
assert res2[0] == 3.0, f"梯度下降结果错误: {res2}"
